/* Connected local demonstration flows. Nothing is submitted to an external service. */
function readFlowState(){try{return JSON.parse(localStorage.getItem('mn-flows')||'{}')}catch{return {}}}
const flowState=Object.assign({searches:[],bookmarks:[],complexSaved:[],complexRecent:[],requests:[],reports:[],posts:[],listings:[],profile:{name:'Зочин',demo:false},draft:{}},readFlowState());
for(const key of ['searches','bookmarks','complexSaved','complexRecent','requests','reports','posts','listings'])if(!Array.isArray(flowState[key]))flowState[key]=[];
let searchPanelTab='region',supportCategory='all',supportQuery='',noticePage=0,myTab='messages',favoriteEdit=false,selectedFavorites=[],signupStep=0,listingStep=0,listingPhotoDraft=[],productArea='';
const flowId=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const flowDate=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'});
function persistFlows(){try{localStorage.setItem('mn-flows',JSON.stringify(flowState));return true}catch{toast('Хадгалах зай хүрэлцэхгүй байна. Зургийн хэмжээг багасгана уу.');return false}}
function goFlow(path){closeOverlay();if(location.hash==='#/'+path)render();else location.hash='/'+path}
function chooseMapCategory(index){category=category===index?-1:index;activeDetail=null;goFlow(category<0?'map':'map/'+category)}
function imageFor(h,index=0){const data=h?.photos?.[index];return typeof data==='string'&&/^data:image\/(jpeg|png);base64,[a-zA-Z0-9+/=]+$/.test(data)?data:h?.local?'assets/listing-placeholder.svg':img(((h?.id||0)+index)%8,1100)}
function localNotice(){return '<p class="notice flow-local-note">Демо горим · Мэдээлэл зөвхөн энэ браузерт хадгалагдана. Гадагш илгээгдэхгүй.</p>'}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function emptyFlow(title,description,action=''){return `<div class="empty"><div class="empty-icon">${icon('folder')}</div><b>${title}</b><p>${description}</p>${action}</div>`}
function flowTabs(tabs,current,action){return `<div class="flow-tabs">${tabs.map(([key,title])=>`<button class="${current===key?'active':''}" onclick="${action}('${key}')">${title}</button>`).join('')}</div>`}
function refreshAccount(){const host=document.getElementById('account-control');if(host)host.innerHTML=`<button class="account-trigger" aria-expanded="false" onclick="toggleAccount(this)">${icon('user-circle')}<span>${flowState.profile.demo?esc(flowState.profile.name)+' · Демо':'Нэвтрэх · Миний булан'}</span>${icon('chevron-down')}</button><div class="account-dropdown" hidden><b>${flowState.profile.demo?esc(flowState.profile.name):'Тавтай морил!'}</b><a href="#/pro">${icon('briefcase')} Өрөө PRO</a><a href="#/my/messages">${icon('user')} Миний булан</a><a href="#/favorites">${icon('heart')} Сонирхсон жагсаалт</a><a href="#/listing/new">${icon('plus')} Зар нэмэх</a><a href="#/my/listings">${icon('apartment')} Миний зарууд</a><a href="#/my/profile">${icon('user-circle')} Миний мэдээлэл</a><a href="#/faq">${icon('help-circle')} Хэрэглэгчийн тусламж</a>${flowState.profile.demo?'<button onclick="exitDemo()">'+icon('logout')+' Демо горимоос гарах</button>':'<a href="#/login">'+icon('user-circle')+' Нэвтрэх / Бүртгүүлэх</a>'}</div>`}
function toggleAccount(button){const menu=button.nextElementSibling;menu.hidden=!menu.hidden;button.setAttribute('aria-expanded',String(!menu.hidden))}
function exitDemo(){flowState.profile.demo=false;persistFlows();goFlow('');refreshAccount();toast('Демо горимоос гарлаа')}

// Search suggestions and recent searches.
function connectedSearchbar(){return `<div class="search-container"><form class="search" onsubmit="connectedSearch(event)"><span class="search-symbol">${icon('search')}</span><input autocomplete="off" aria-label="Байршил хайх" aria-controls="search-suggestions" aria-expanded="false" placeholder="Дүүрэг, хотхон эсвэл зарын дугаараар хайх" value="${esc(query)}" name="query" onfocus="showSearchSuggestions(this)" oninput="showSearchSuggestions(this)"><button class="primary">Хайх</button></form><div class="search-suggestions" id="search-suggestions" hidden></div></div>`}
function showSearchSuggestions(input){const panel=input.closest('.search-container').querySelector('.search-suggestions');const text=input.value.trim().toLowerCase();const choices=searchPanelTab==='region'?areas:searchPanelTab==='complex'?[...new Set(homes.filter(isPublicListing).map(h=>h.name))]:homes.filter(isPublicListing).map(h=>String(h.id));const results=choices.filter(item=>item.toLowerCase().includes(text)).slice(0,7);panel.hidden=false;input.setAttribute('aria-expanded','true');panel.innerHTML=`<div class="suggestion-tabs">${[['region','Дүүрэг'],['complex','Хотхон'],['id','Зарын дугаар']].map(([key,title])=>`<button type="button" class="${searchPanelTab===key?'active':''}" onclick="searchPanelTab='${key}';showSearchSuggestions(this.closest('.search-container').querySelector('input'))">${title}</button>`).join('')}</div>${!text&&flowState.searches.length?`<div class="suggestion-label">Сүүлд хайсан <button onclick="flowState.searches=[];persistFlows();showSearchSuggestions(this.closest('.search-container').querySelector('input'))">Арилгах</button></div>${flowState.searches.slice(0,4).map(value=>`<button class="suggestion-row" data-value="${esc(value)}" onclick="chooseSearch(this)">${icon('clock')}<span>${esc(value)}</span>${icon('arrow-up-right')}</button>`).join('')}`:''}<div class="suggestion-label">${text?'Хайлтын үр дүн':'Санал болгох'}</div>${results.map(value=>`<button class="suggestion-row" data-value="${esc(value)}" onclick="chooseSearch(this)">${icon('search')}<span>${esc(value)}</span>${icon('arrow-right')}</button>`).join('')||'<p class="suggestion-label">Тохирох жишээ мэдээлэл олдсонгүй.</p>'}`}
function chooseSearch(button){runSearch(button.dataset.value)}
function connectedSearch(event){event.preventDefault();runSearch(new FormData(event.target).get('query'))}
function runSearch(value){query=String(value||'').trim().slice(0,120);activeDetail=null;if(areas.includes(query)||MONGOLIA_PROVINCES.includes(query))filter.locations=[];if(query){flowState.searches=[query,...flowState.searches.filter(v=>v!==query)].slice(0,10);persistFlows()}const exact=homes.find(h=>String(h.id)===query);if(exact){detail(exact.id);return}category=-1;goFlow('map')}
function saveCurrentSearch(){flowState.bookmarks.unshift({id:flowId(),name:query||'Улаанбаатар · Бүх дүүрэг',query,category,filter:{...filter}});persistFlows();toast('Хайлт хадгалагдлаа')}
function applySavedSearch(id){const item=flowState.bookmarks.find(v=>v.id===id);if(!item)return;query=item.query;category=item.category;filter=normalizeMongolianFilter(item.filter);activeDetail=null;goFlow(category>=0?'map/'+category:'map')}

// Filters apply to the actual demo list and district marker counts.
function openConnectedFilters(kind){openMongolianFilter(kind)}
function applyConnectedFilters(event,kind){applyMongolianFilter(event,kind)}
function extraFilterMatch(h){return matchesMongolianListing(h)}
// Favourites include editable rooms, building histories and named searches.
function buildingNames(){return [...new Set(homes.filter(isPublicListing).map(h=>h.name))]}
function buildingCard(index){const name=buildingNames()[index],items=homes.filter(h=>h.name===name&&isPublicListing(h)),h=items[0];return `<article class="building-card"><a href="#/complex/${index}"><img src="${h.photos?.[0]||img(index)}" alt="${esc(name)}"><span class="badge">${esc(h.area)}</span><h3>${esc(name)}</h3><p>${items.length} жишээ зар · ${h.year} он</p></a><button class="building-heart" onclick="toggleBuilding(${index})" aria-label="Хотхон хадгалах">${heartIcon(flowState.complexSaved.includes(name))}</button></article>`}
function toggleBuilding(index){const name=buildingNames()[index];flowState.complexSaved=flowState.complexSaved.includes(name)?flowState.complexSaved.filter(v=>v!==name):[name,...flowState.complexSaved];persistFlows();render();toast('Хотхоны жагсаалт шинэчлэгдлээ')}
function connectedFavorites(){const tabs=['Сүүлд үзсэн байр','Хадгалсан байр','Сүүлд үзсэн хотхон','Хадгалсан хотхон','Дуртай хайлт'];const ids=(favTab===0?recent:saved).filter(id=>homes.some(h=>h.id===id&&isPublicListing(h)));const names=favTab===2?flowState.complexRecent:flowState.complexSaved;return `<div class="wrap"><h1 class="page-title centered">Сонирхсон жагсаалт</h1><div class="subnav">${tabs.map((t,i)=>`<button class="${favTab===i?'active':''}" onclick="favTab=${i};favoriteEdit=false;selectedFavorites=[];render()">${t}</button>`).join('')}</div>${favTab<2?`<div class="section-head"><p>${ids.length} зар · Браузерт хадгалагдана</p><div><button onclick="favoriteEdit=!favoriteEdit;selectedFavorites=[];render()">${favoriteEdit?'Дуусгах':'Засах'}</button>${favoriteEdit?'<button onclick="removeSelectedFavorites()">Сонгосныг хасах</button>':''}</div></div>${ids.length?`<div class="cards">${ids.map(id=>homes.find(h=>h.id===id)).filter(Boolean).map(h=>`<div class="editable-card">${favoriteEdit?`<label class="select-favorite"><input type="checkbox" ${selectedFavorites.includes(h.id)?'checked':''} onchange="selectFavorite(${h.id},this.checked)"> Сонгох</label>`:''}${card(h)}</div>`).join('')}</div>`:emptyFlow('Жагсаалт хоосон байна','Таалагдсан зарынхаа ♡ товчийг дараарай.','<a href="#/map"><button class="primary">Байр хайх</button></a>')}`:favTab<4?`<div class="cards">${names.map(name=>buildingNames().indexOf(name)).filter(i=>i>=0).map(buildingCard).join('')}</div>${!names.length?emptyFlow('Хотхон нэмээгүй байна','Хотхоны мэдээлэлд зочилж, ♡ товчоор хадгалаарай.','<a href="#/complexes"><button>Хотхонууд үзэх</button></a>'):''}`:flowState.bookmarks.length?flowState.bookmarks.map(item=>`<div class="saved-search"><div><b>${esc(item.name)}</b><p>${item.category>=0?types[item.category]:'Бүх төрөл'} · ${item.filter.minSize||0} м²-с дээш</p></div><button onclick="applySavedSearch('${item.id}')">Хайх →</button><button aria-label="Хайлт хасах" onclick="deleteFlowItem('bookmarks','${item.id}')">${icon('close')}</button></div>`).join(''):emptyFlow('Хадгалсан хайлт алга','Газрын зураг дээрх “Хайлт хадгалах” товчийг дарна уу.','<a href="#/map"><button>Хайлт үүсгэх</button></a>')}</div>`}
function selectFavorite(id,on){selectedFavorites=on?[...selectedFavorites,id]:selectedFavorites.filter(v=>v!==id)}
function removeSelectedFavorites(){if(favTab===0){recent=recent.filter(id=>!selectedFavorites.includes(id));localStorage.setItem('mn-recent',JSON.stringify(recent))}else{saved=saved.filter(id=>!selectedFavorites.includes(id));localStorage.setItem('mn-saved',JSON.stringify(saved))}selectedFavorites=[];render()}
function deleteFlowItem(key,id){if(!['bookmarks','requests','reports','posts','listings'].includes(key))return;flowState[key]=flowState[key].filter(item=>item.id!==id);persistFlows();render()}
function connectedBuilding(index){
 const name=buildingNames()[index];if(!name)return emptyFlow('Хотхон олдсонгүй','Жагсаалтаас дахин сонгоно уу.');
 if(!flowState.complexRecent.includes(name)){flowState.complexRecent.unshift(name);flowState.complexRecent=flowState.complexRecent.slice(0,30);persistFlows()}
 const items=homes.filter(h=>h.name===name&&isPublicListing(h)),h=items[0];
 const prices=h.local?'<p class="notice">Бодит хэлцлийн түүх холбогдоогүй. Зар оруулагчийн үнийг доорх заруудаас харна уу.</p>':'<p class="notice">Загвар дүрслэл · Бодит зах зээлийн ханш биш · Үнэ, ₮</p><div class="price-bars">'+[0,1,2,3,4,5].map(v=>'<div><b>'+formatMnt(h.price===null?null:Math.round(h.price*(.9+v*.03)/1000)*1000)+'</b><i style="height:'+(65+v*13)+'px"></i><span>'+(v+6)+' сар</span></div>').join('')+'</div>';
 return `<div class="wrap"><a href="#/complexes" class="back-link">← Хотхоны жагсаалт</a><div class="building-hero"><img src="${imageFor(h)}" alt="${esc(name)}"><div><span class="badge">${h.local?'ТАНЫ ДЕМО ЗАР':'ХОТХОН · ЖИШЭЭ'}</span><h1>${esc(name)}</h1><p>${esc([h.province||'Улаанбаатар',h.area].join(' · '))}</p><div class="chips"><span>${h.year?esc(h.year)+' он':'Он оруулаагүй'}</span><span>${h.totalFloors?esc(h.totalFloors)+' давхар':'Нийт давхар оруулаагүй'}</span><span>${items.length} зар</span></div><button class="primary" onclick="toggleBuilding(${index})">${heartIcon(flowState.complexSaved.includes(name))}<span>${flowState.complexSaved.includes(name)?'Хадгалсан':'Хотхон хадгалах'}</span></button>${listingLocationPoint(h)?'<button onclick="openListingMapsMe('+h.id+')">MAPS.ME ↗</button>':''}</div></div><div class="flow-tabs"><a href="#building-info" onclick="event.preventDefault();document.getElementById('building-info').scrollIntoView({behavior:'smooth'})">Хотхоны мэдээлэл</a><a href="#building-prices" onclick="event.preventDefault();document.getElementById('building-prices').scrollIntoView({behavior:'smooth'})">Үнийн хандлага</a><a href="#building-rooms" onclick="event.preventDefault();document.getElementById('building-rooms').scrollIntoView({behavior:'smooth'})">Зарууд (${items.length})</a></div><section id="building-info"><h2>Хотхоны мэдээлэл</h2>${listingRows([['Байршил',listingAddress(h)],['Ашиглалтад орсон он',h.year],['Нийт давхар',h.totalFloors],['Зогсоол',listingParkingText(h)],['Цахилгаан шат',h.elevator?'Байгаа':'Байхгүй']])}</section><section id="building-prices"><h2>Үнийн мэдээлэл</h2>${prices}</section><section id="building-rooms"><h2>Хотхоны зарууд</h2><div class="cards">${items.map(card).join('')}</div></section></div>`;
}

// Account pages intentionally simulate a session without retaining credentials.
function authPage(mode='welcome'){if(mode==='signup')return signupPage();return `<section class="login flow-auth"><a class="logo" href="#/"><img src="assets/oroo.png" alt="Өрөө"></a><h2>${mode==='email'?'Имэйлээр нэвтрэх':'Гэрээ олох аяллаа<br>хамт эхлүүлье'}</h2>${mode==='email'?`<form onsubmit="demoLogin(event)">${field('Имэйл','email','','email','required autocomplete="off" placeholder="demo@example.com"')}<label class="field">Нууц үг<div class="password-field"><input name="password" type="password" minlength="8" required autocomplete="off"><button type="button" aria-label="Нууц үг харуулах" onclick="togglePassword(this)">${icon('eye')}</button></div></label><button class="primary">Демо нэвтрэлт шалгах</button></form><div class="auth-links"><button onclick="passwordRecovery()">Нууц үг сэргээх</button><a href="#/login/signup">Имэйлээр бүртгүүлэх</a></div>`:`<button class="kakao" onclick="authInfo('Kakao')">${icon('message')}<span>Kakao-гаар нэвтрэх</span></button><a class="button-link" href="#/login/email">${icon('mail')}<span>Имэйлээр нэвтрэх</span></a><button onclick="authInfo('Facebook')">f Facebook-ээр нэвтрэх</button><div class="auth-divider">эсвэл</div><a class="button-link" href="#/login/signup">Шинэ бүртгэл</a><button class="primary" onclick="enterDemo()">Зочин демо горимоор үзэх</button>`}<p class="notice">Демо интерфэйс. Бодит нууц үг бүү оруулна уу. Нууц үг, имэйл хадгалагдахгүй; серверт илгээгдэхгүй.</p></section>`}
function enterDemo(name){flowState.profile={...flowState.profile,name:name||flowState.profile.name||'Демо зочин',demo:true};persistFlows();goFlow('my/messages');toast('Демо горимд орлоо')}
function demoLogin(event){event.preventDefault();event.target.reset();enterDemo('Демо хэрэглэгч')}
function togglePassword(button){const input=button.previousElementSibling;input.type=input.type==='password'?'text':'password';button.innerHTML=icon(input.type==='password'?'eye':'eye-off');button.setAttribute('aria-label',input.type==='password'?'Нууц үг харуулах':'Нууц үг нуух')}
function passwordRecovery(){modal(`<h2>Нууц үг сэргээх</h2><p class="notice">Демо шалгалт. Бодит сэргээх имэйл илгээхгүй.</p><form onsubmit="event.preventDefault();this.reset();modal('<h2>Демо хүсэлтийг шалгалаа</h2><p>Имэйл илгээгээгүй. Серверийн баталгаажуулалт холбогдоогүй.</p><button class=\"primary\" onclick=\"closeOverlay()\">Ойлголоо</button>')">${field('Имэйл','email','','email','required placeholder="demo@example.com"')}<button class="primary">Демо хүсэлт шалгах</button></form>`)}
function signupPage(){return `<section class="login flow-auth"><h1>Бүртгүүлэх</h1><div class="wizard-steps">${['Нөхцөл','Баталгаажуулалт','Мэдээлэл'].map((t,i)=>`<span class="${i===signupStep?'active':''}">${i+1}. ${t}</span>`).join('')}</div><p class="notice">Туршилтын бүртгэл. Бодит үйлчилгээний бүртгэл үүсгэхгүй.</p>${signupStep===0?`<form onsubmit="event.preventDefault();signupStep=1;render()"><label class="check"><input type="checkbox" required> Демо үйлчилгээний нөхцөлтэй танилцсан <a href="#/terms" target="_blank">Үзэх ↗</a></label><label class="check"><input type="checkbox" required> Демо хадгалалтын мэдээлэлтэй танилцсан <a href="#/privacy" target="_blank">Үзэх ↗</a></label><button class="primary">Үргэлжлүүлэх</button></form>`:signupStep===1?`<form onsubmit="checkDemoCode(event)"><p>Демо баталгаажуулах код: <b>123456</b></p><p class="notice">SMS илгээхгүй. Энэ код нь зөвхөн алхмыг турших зориулалттай.</p>${field('Демо код','code','','text','required inputmode="numeric" pattern="[0-9]{6}"')}<p class="form-error" role="alert"></p><button class="primary">Код шалгах</button><button type="button" onclick="signupStep=0;render()">Буцах</button></form>`:`<form onsubmit="completeSignup(event)">${field('Дэлгэцийн нэр','name','','text','required maxlength="30"')}${field('Имэйл · демо','email','','email','required autocomplete="off"')}${field('Нууц үг · демо','password','','password','required minlength="8" autocomplete="off"')}${field('Нууц үг давтах','confirm','','password','required minlength="8" autocomplete="off"')}<p class="form-error" role="alert"></p><button class="primary">Демо горим үүсгэх</button><button type="button" onclick="signupStep=1;render()">Буцах</button></form>`}</section>`}
function checkDemoCode(event){event.preventDefault();if(new FormData(event.target).get('code')!=='123456'){event.target.querySelector('.form-error').textContent='Демо код 123456 байна.';return}signupStep=2;render()}
function completeSignup(event){event.preventDefault();const f=new FormData(event.target);if(f.get('password')!==f.get('confirm')){event.target.querySelector('.form-error').textContent='Нууц үг таарахгүй байна.';return}const name=String(f.get('name')).trim().slice(0,30);event.target.reset();signupStep=0;enterDemo(name)}

// Help centre, notices and locally stored enquiry/report history.
const supportTabs=[['faq','Түгээмэл асуулт'],['inquiry','1:1 лавлагаа'],['notice','Мэдээ, зарлал']];
const noticeItems=[['Монгол хэл дээрх хувилбарт тавтай морил','Хайлт, газрын зураг, хадгалсан зар болон хувийн булангийн шинэ урсгалуудыг туршиж үзээрэй.'],['Шинэ хайлт ба хадгалсан нөхцөл','Дүүрэг, хотхон, зарын дугаараар хайж, шүүлтүүртэй хайлтаа хадгалах боломжтой.'],['Орон нутгийн демо хадгалалт','Маягтаар үүсгэсэн хүсэлт, зар, нийтлэлүүд зөвхөн таны браузерт хадгалагдана.'],['Нууц үгийн мэдээлэл','Бодит нууц үгээ демо маягтад бүү оруулаарай. Нууц үг серверт илгээгдэхгүй, хадгалагдахгүй.'],['Хотхоны мэдээлэл','Хотхоны дэлгэрэнгүй мэдээлэл, хадгалсан болон сүүлд үзсэн хотхонуудыг сонирхсон жагсаалтаас үзнэ.'],['Мэдээллийн жишээ өгөгдөл','Зарын зураг, үнэ болон тоон үзүүлэлтүүд нь танилцуулгын өгөгдөл болно.']];
function helpHeading(current){return `<h1 class="page-title centered">Хэрэглэгчийн тусламж</h1>${flowTabs(supportTabs,current,'openSupportTab')}`}
function openSupportTab(key){goFlow(key)}
function supportPage(route,id){if(route==='notice'&&id!==undefined){const item=noticeItems[Number(id)];if(!item)return emptyFlow('Мэдээ олдсонгүй','Жагсаалтаас дахин сонгоно уу.');return `<div class="wrap support-wrap">${helpHeading('notice')}<article class="notice-detail"><span class="badge">ДЕМО МЭДЭЭ</span><h2>${item[0]}</h2><p class="muted">2026.11.09</p><p>${item[1]}</p></article><button onclick="goFlow('notice')">← Жагсаалт руу</button></div>`}
 if(route==='notice'){const visible=noticeItems.map((v,i)=>({v,i})).filter(({v})=>v[0].toLowerCase().includes(supportQuery.toLowerCase()));return `<div class="wrap support-wrap">${helpHeading(route)}${supportSearch()}<table class="table notice-table"><thead><tr><th>№</th><th>Гарчиг</th><th>Огноо</th></tr></thead><tbody>${visible.slice(noticePage*5,noticePage*5+5).map(({v,i})=>`<tr><td>${i+1}</td><td><a href="#/notice/${i}">${v[0]}</a></td><td>2026.11.09</td></tr>`).join('')}</tbody></table>${!visible.length?emptyFlow('Хайлтын үр дүн алга','Өөр түлхүүр үг оруулна уу.'):''}<div class="pagination">${Array.from({length:Math.ceil(visible.length/5)},(_,i)=>`<button class="${noticePage===i?'primary':''}" onclick="noticePage=${i};render()">${i+1}</button>`).join('')}</div></div>`}
 if(route==='inquiry')return `<div class="wrap support-wrap">${helpHeading(route)}<div class="section-head"><p>Үйлчилгээний талаар асуугаарай.</p><a href="#/my/support">Миний лавлагааны түүх →</a></div>${localNotice()}<form class="inquiry-form" onsubmit="submitSupport(event)"><label class="field">Ангилал<select name="kind"><option value="support">Үйлчилгээний асуулт</option><option value="advertising">Зар сурталчилгаа</option><option value="agent">Агентын бүртгэл</option></select></label>${field('Гарчиг','title','','text','required maxlength="100"')}${field('Демо хариу авах имэйл','email','','email','required placeholder="demo@example.com"')}<label class="field">Агуулга<textarea name="body" required maxlength="2000" placeholder="Асуултаа дэлгэрэнгүй бичнэ үү."></textarea></label><label class="check"><input required type="checkbox"> Энэ браузерт демо хүсэлт хадгалахыг зөвшөөрнө</label><p class="muted">Имэйлийг хадгалахгүй. Бодит хариу, мэдэгдэл илгээхгүй.</p><div class="flow-actions"><button type="reset">Цэвэрлэх</button><button class="primary">Демо хүсэлт хадгалах</button></div></form></div>`;
 const rows=faqs.map(([q,a],i)=>({q,a,i})).filter(item=>(supportCategory==='all'||(supportCategory==='search'&&item.i<2)||(supportCategory==='account'&&item.i===4)||(supportCategory==='listing'&&[2,3].includes(item.i)))&&`${item.q} ${item.a}`.toLowerCase().includes(supportQuery.toLowerCase()));return `<div class="wrap support-wrap">${helpHeading('faq')}<p class="support-intro">Танд хэрэгтэй <em>асуулт, хариултуудыг</em> нэг дор цуглууллаа.</p>${supportSearch()}<div class="chips">${[['all','Бүгд'],['search','Хайлт / хадгалах'],['account','Бүртгэл'],['listing','Зарын мэдээлэл']].map(([k,t])=>`<button class="chip ${supportCategory===k?'active':''}" onclick="supportCategory='${k}';render()">${t}</button>`).join('')}</div>${rows.map(item=>`<details class="accordion"><summary><span class="question-label">Q.</span> ${item.q}</summary><p>${item.a}</p></details>`).join('')||emptyFlow('Хариулт олдсонгүй','Өөрөөр хайх эсвэл 1:1 лавлагаа үлдээнэ үү.')}<div class="support-bottom"><b>Хариултаа олоогүй юу?</b><a href="#/inquiry"><button>1:1 лавлагаа →</button></a></div></div>`}
function supportSearch(){return `<form class="support-search" onsubmit="event.preventDefault();supportQuery=this.elements.keyword.value.trim();noticePage=0;render()"><input name="keyword" value="${esc(supportQuery)}" aria-label="Тусламж хайх" placeholder="Асуулт, түлхүүр үгээр хайх"><button>${icon('search')} Хайх</button></form>`}
function submitSupport(event){event.preventDefault();const f=new FormData(event.target);flowState.requests.unshift({id:flowId(),kind:String(f.get('kind')),title:String(f.get('title')),body:String(f.get('body')),date:flowDate(),status:'Орон нутгийн демо'});if(persistFlows()){event.target.reset();goFlow('my/support');toast('Хүсэлтийг энэ браузерт хадгаллаа')}}
function connectedContact(id,kind='message'){const h=homes.find(h=>h.id===id&&isPublicListing(h));if(!h)return;modal(`<h2>${kind==='phone'?'Утасны лавлагаа':'Зарын тухай асуух'}</h2><div class="contact-property"><img src="${imageFor(h)}" alt="Байрны зураг"><div><b>${esc(h.name)}</b><p>Зар № ${id} · ${esc(h.area)}</p></div></div>${listingContactRows(h)}${localNotice()}<form onsubmit="submitPropertyRequest(event,${id},'${kind}')"><label class="field">Асуулт<textarea name="body" required maxlength="1000" placeholder="Нүүх өдөр, байр үзэх цаг болон бусад асуултаа бичээрэй."></textarea></label><label class="check"><input required type="checkbox"> Демо хүсэлт гэдгийг ойлгосон</label><button class="primary">Демо лавлагаа хадгалах</button></form><p class="muted">Агент руу мессеж эсвэл дуудлага илгээгдэхгүй.</p>`)}
function submitPropertyRequest(event,id,kind){event.preventDefault();const h=homes.find(h=>h.id===id&&isPublicListing(h));if(!h||!['message','phone'].includes(kind))return;const identity=officeIdentity(h),body=String(new FormData(event.target).get('body')||'').trim();if(!body||body.length>1000)return;flowState.requests.unshift({id:flowId(),kind,propertyId:id,officeId:identity?.officeId,agentId:identity?.agentId,title:'Зар № '+id,body,date:flowDate(),status:'Орон нутгийн демо'});if(persistFlows()){closeOverlay();toast('Хадгаллаа · Миний булангаас үзэх боломжтой')}else flowState.requests.shift()}
function connectedReport(id){modal(`<h2>Зар № ${id} · Мэдээлэх</h2>${localNotice()}<form onsubmit="submitReport(event,${id})"><label class="field">Шалтгаан<select name="reason"><option>Зарын мэдээлэл зөрүүтэй</option><option>Байрны зураг тохирохгүй</option><option>Гэрээ хийгдсэн зар</option><option>Давхардсан зар</option><option>Бусад</option></select></label><label class="field">Дэлгэрэнгүй<textarea name="body" required maxlength="1000"></textarea></label><button class="primary">Демо мэдээлэл хадгалах</button></form>`)}
function submitReport(event,id){event.preventDefault();const f=new FormData(event.target);flowState.reports.unshift({id:flowId(),propertyId:id,title:String(f.get('reason')),body:String(f.get('body')),date:flowDate(),status:'Орон нутгийн демо'});if(persistFlows()){closeOverlay();toast('Мэдээллийг хадгаллаа · Миний булан → Мэдээлсэн зар')}}
const myTabs=[['messages','Зарын лавлагаа'],['phone','Утасны лавлагаа'],['support','1:1 хүсэлт'],['reports','Мэдээлсэн зар'],['stories','Миний түүх'],['listings','Миний зар'],['profile','Миний мэдээлэл']];
function openMyTab(tab){goFlow('my/'+tab)}
function myPage(tab='messages'){myTab=tab;const title=myTabs.find(v=>v[0]===tab)?.[1]||'Миний булан';let content='';
 if(tab==='profile')content=`<form class="profile-form" onsubmit="saveProfile(event)"><div class="profile-avatar">${esc((flowState.profile.name||'З').slice(0,1))}</div>${field('Дэлгэцийн нэр','name',flowState.profile.name,'text','required maxlength="30"')}<label class="check"><input name="tips" type="checkbox" ${flowState.profile.tips?'checked':''}> Демо зөвлөмжийн тохиргоо</label><p class="notice">Энэ тохиргоо зөвхөн локал демод үйлчилнэ. Бодит мэдэгдэл явуулахгүй.</p><button class="primary">Хадгалах</button></form>`;
 else if(tab==='listings')content=`<div class="section-head"><h2>Миний зарууд · ${flowState.listings.length}</h2><a href="#/listing/new"><button class="primary">＋ Зар нэмэх</button></a></div>${localNotice()}${flowState.listings.length?`<div class="cards">${flowState.listings.map(h=>`<div>${card(h)}<button class="edit-listing-button" onclick="editLocalListing(${h.id})">${icon('file-text')} Зар засах</button><button class="edit-listing-button" onclick="previewSavedListingLocation(${h.id})">${icon('pin')}Газрын зураг</button><button onclick="removeLocalListing(${h.id})">Демо зар хасах</button></div>`).join('')}</div>`:emptyFlow('Одоогоор зар үүсгээгүй','Байрны мэдээллээ оруулж, демо зарыг браузерт хадгалаарай.','<a href="#/listing/new"><button>Зар үүсгэх</button></a>')}`;
 else{const list=tab==='reports'?flowState.reports:tab==='stories'?flowState.posts:flowState.requests.filter(item=>tab==='messages'?item.kind==='message':tab==='phone'?item.kind==='phone':!['message','phone'].includes(item.kind));content=`<div class="section-head"><h2>${title}</h2><span>${list.length} бүртгэл</span></div>${localNotice()}${list.map(item=>`<details class="history-row"><summary><span><b>${esc(item.title)}</b><small>${esc(item.date||'')} · Орон нутгийн демо</small></span>${icon('chevron-down')}</summary><div class="history-body"><p>${esc(item.body)}</p>${adminHistoryReply(item)}${tab==='stories'&&item.province?'<a href="'+nhUrl(nhCleanScope(item),'stories')+'">'+esc(nhScopeLabel(item))+' →</a>':''}${item.officeId&&officePublicModel(item.officeId)?'<a href="#/offices/'+esc(item.officeId)+'">Байгууллагын профайл →</a>':''}${item.propertyId?`<button onclick="detail(${item.propertyId})">Зар үзэх →</button>`:''}<button onclick="deleteFlowItem('${tab==='reports'?'reports':tab==='stories'?'posts':'requests'}','${item.id}')">Бүртгэл хасах</button></div></details>`).join('')||emptyFlow('Бүртгэл алга','Зар, лавлагаа болон нийтлэлтэй холбоотой таны демо үйлдлүүд энд харагдана.')}`}
 return `<div class="wrap my-wrap"><div class="my-heading"><div><div class="eyebrow">MY HOME</div><h1>Миний булан</h1></div><span class="badge">${esc(flowState.profile.name)} · ${flowState.profile.demo?'Демо горим':'Зочин'}</span></div>${flowTabs(myTabs,tab,'openMyTab')}${content}</div>`}
function saveProfile(event){event.preventDefault();const f=new FormData(event.target);flowState.profile={...flowState.profile,name:String(f.get('name')).trim().slice(0,30)||'Зочин',tips:f.has('tips')};persistFlows();refreshAccount();toast('Дэлгэцийн нэр хадгалагдлаа')}

// A complete local listing wizard with explicit review before local saving.
function listingWizard(){return renderListingEditor()}
function advanceListing(event){submitListingEditor(event)}
async function readListingPhotos(input){await readEditorPhotos(input)}
function hydrateLocalListings(){flowState.listings=flowState.listings.filter(h=>h&&Number.isFinite(h.id)&&typeof h.area==='string'&&(areas.includes(h.area)||h.schemaVersion===2&&MONGOLIA_PROVINCES.includes(h.province))&&Number.isInteger(h.type)&&h.type>=0&&h.type<types.length&&(Number.isFinite(h.price)&&h.price>=0||h.price===null)&&typeof h.name==='string');for(const h of flowState.listings){if(!homes.some(item=>item.id===h.id))homes.push(h)}}
function removeLocalListing(id){const index=homes.findIndex(h=>h.id===id&&h.local);if(index>=0)homes.splice(index,1);flowState.listings=flowState.listings.filter(h=>h.id!==id);if(flowState.draft.editId===id){clearTimeout(editorSaveTimer);flowState.draft={};listingPhotoDraft=[];listingStep=0;editorReady=false}saved=saved.filter(v=>v!==id);recent=recent.filter(v=>v!==id);localStorage.setItem('mn-saved',JSON.stringify(saved));localStorage.setItem('mn-recent',JSON.stringify(recent));persistFlows();render()}

// Agent products and tailored recommendations.
function agentProducts(kind='overview'){const plans=[['general','Ердийн зар','Байршлаар харагдах зар, үндсэн мэдээлэл.'],['package','Багц үйлчилгээ','Олон зарыг нэг нөхцөлөөр удирдах боломж.'],['premium','Премиум зар','Сонгосон бүсэд илүү тод харагдах байршуулалт.']];return `<div class="wrap"><div class="agent-hero"><div class="eyebrow">PRO · АГЕНТЫН ҮЙЛЧИЛГЭЭ</div><h1>Таны зарыг зөв хүнд хүргэнэ.</h1><p>Бүтээгдэхүүнээ сонгоод, байршлаар санал авах хүсэлтээ бэлтгээрэй.</p><a href="#/listing/new"><button class="primary">Зар нэмэх</button></a></div><div class="flow-tabs">${[['overview','Танилцуулга'],...plans.map(v=>[v[0],v[1]])].map(([k,t])=>`<a class="${kind===k?'active':''}" href="#/agent/products/${k}">${t}</a>`).join('')}</div><div class="product-search"><label class="field">Зар байрлуулах дүүрэг<select id="product-area">${areas.map(v=>`<option ${v===(productArea||areas[0])?'selected':''}>${v}</option>`).join('')}</select></label><button onclick="applyProductArea()">Бүтээгдэхүүн хайх</button></div><div class="section-head"><h2>${esc(productArea||areas[0])} · Жишээ бүтээгдэхүүн</h2></div><div class="content-grid">${plans.filter(v=>kind==='overview'||v[0]===kind).map(([key,t,desc],i)=>`<article class="plan-card"><span class="badge">${key.toUpperCase()}</span><h2>${t}</h2><p>${desc}</p><ul><li>Зар удирдах интерфэйс</li><li>Дүүрэг, төрлөөр сонголт</li><li>30 хоногийн жишээ хугацаа</li></ul><p class="notice">Жишээ бүтээгдэхүүн · Төлбөр авахгүй</p><button class="primary" onclick="configureProduct('${key}')">Сонгох →</button></article>`).join('')}</div><h2>Агентын зарууд</h2><div class="cards">${homes.filter(isPublicListing).slice(0,4).map(card).join('')}</div></div>`}
function configureProduct(kind){const area=document.getElementById('product-area')?.value||areas[0];modal(`<h2>Бүтээгдэхүүний хүсэлт</h2><p>${esc(kind.toUpperCase())} · ${esc(area)}</p>${localNotice()}<form onsubmit="submitProductRequest(event,'${kind}','${area}')"><label class="field">Хугацаа<select name="period"><option>30 хоног</option><option>60 хоног</option><option>90 хоног</option></select></label><label class="field">Зарын тоо<input type="number" name="count" min="1" max="100" value="5" required></label><button class="primary">Демо хүсэлт хадгалах</button></form>`)}
function submitProductRequest(event,kind,area){event.preventDefault();const f=new FormData(event.target);flowState.requests.unshift({id:flowId(),kind:'advertising',title:kind.toUpperCase()+' · '+area,body:f.get('count')+' зар · '+f.get('period'),date:flowDate(),status:'Орон нутгийн демо'});if(persistFlows())goFlow('my/support')}
function recommendationModal(){modal(`<h2>Танд тохирох орон зайгаа олоорой</h2><p class="notice">Жишээ өгөгдлийг нөхцөлөөр шүүнэ. Бодит AI үйлчилгээ дуудаагүй.</p><form onsubmit="applyRecommendation(event)"><label class="field">Байршил<select name="area"><option value="">Бүх дүүрэг</option>${areas.map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field">Зарын төрөл<select name="type"><option value="-1">Бүгд</option>${types.map((t,i)=>`<option value="${i}">${t}</option>`).join('')}</select></label>${field('Сарын түрээсийн дээд үнэ, ₮','max',2000000,'number','required min="1" max="100000000000"')}<label class="check"><input name="pet" type="checkbox"> Амьтан зөвшөөрдөг</label><button class="primary">Тохирох зарууд харах</button></form>`)}
function applyRecommendation(event){event.preventDefault();const f=new FormData(event.target);filter={...defaultFilter(),max:Number(f.get('max')),pet:f.has('pet')};query=String(f.get('area'));category=Number(f.get('type'));activeDetail=null;goFlow(category>=0?'map/'+category:'map')}
function recommendationHomes(){const list=homes.filter(isPublicListing);if(activeTag===1)return list.filter(h=>h.size<=30);if(activeTag===2)return list.filter(h=>h.deal==='sale');if(activeTag===3)return list.filter(h=>h.id%2===0);if(activeTag===4)return list.filter(h=>h.type===4);if(activeTag===5)return [...list].sort((a,b)=>b.id-a.id);return list}
function applyProductArea(){productArea=document.getElementById('product-area').value;render()}
function savedCommunityPost(event){event.preventDefault();const f=new FormData(event.target);flowState.posts.unshift({id:flowId(),title:String(f.get('title')),body:String(f.get('body')),date:flowDate()});if(persistFlows()){closeOverlay();render();toast('Түүхийг энэ браузерт хадгаллаа')}}
function decorateCommunity(){const host=document.getElementById('posts');if(host)host.insertAdjacentHTML('afterbegin',flowState.posts.filter(item=>item.adminStatus!=='hidden').map(item=>`<div class="post"><span class="badge">ТАНЫ ДЕМО ТҮҮХ</span><h3>${esc(item.title)}</h3><p>${esc(item.body)}</p></div>`).join(''))}
function flowRoute(parts){const [route,sub,third]=parts;if(route==='offices')return officePage(sub);if(route==='admin')return adminPage(sub||'overview');if(route==='pro')return proPage(sub||'dashboard');if(route==='notice')return adminPublicNotices(sub);if(route==='more')return mobileMorePage();if(route==='search')return mobileSearchPage();if(route==='login')return authPage(sub||'welcome');if(route==='my')return myPage(sub||'messages');if(route==='listing')return listingWizard();if(['faq','inquiry','notice'].includes(route))return supportPage(route,sub);if(route==='complexes')return `<div class="wrap"><h1 class="page-title">Хотхонууд</h1><p class="notice">Жишээ хотхонуудын мэдээлэл</p><div class="cards">${buildingNames().map((_,i)=>buildingCard(i)).join('')}</div></div>`;if(route==='complex')return connectedBuilding(Number(sub));if(route==='agent')return agentProducts(third||'overview');return null}

function connectedGallery(id,index=0){const h=homes.find(item=>item.id===id&&isPublicListing(item));if(!h)return;const count=h.photos?.length||(h.local?1:4);index=(index+count)%count;modal(`<div class="gallery-heading" data-gallery-listing="${id}"><h2>${esc(h.name)}</h2><span>${index+1} / ${count}</span></div><div class="gallery-main"><button aria-label="Өмнөх зураг" onclick="connectedGallery(${id},${index-1})">${icon('chevron-left')}</button><img src="${imageFor(h,index)}" alt="Байрны зураг ${index+1}"><button aria-label="Дараах зураг" onclick="connectedGallery(${id},${index+1})">${icon('chevron-right')}</button></div><div class="gallery-thumbnails">${Array.from({length:count},(_,i)=>`<button class="${i===index?'active':''}" onclick="connectedGallery(${id},${i})"><img src="${imageFor(h,i)}" alt="Зураг ${i+1}"></button>`).join('')}</div>`);document.querySelector('.modal').classList.add('gallery-modal')}
function shareProperty(id){const url=(location.href?.split('#')[0]||location.origin+location.pathname)+'#/room/'+id;const show=()=>modal(`<h2>Зарын холбоос</h2><label class="field">Хуулах холбоос<input value="${esc(url)}" readonly onclick="this.select()"></label><p class="notice">Локал файлтай холбоосыг өөр төхөөрөмжөөс нээх боломжгүй. Нийтлэхийн өмнөх демо хувилбар.</p>`);if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url).then(()=>toast('Холбоос хууллаа')).catch(show);else show()}
function openNearbyFlow(tab='convenience'){const tabs=[['convenience','Тав тух'],['security','Аюулгүй байдал'],['school','Сургууль'],['transport','Тээвэр']];const items={convenience:[['Дэлгүүр','150 м'],['Эмийн сан','320 м'],['Кафе','280 м']],security:[['Цагдаагийн хэсэг','800 м'],['Гэрэлтүүлэг','Орц орчим'],['Камер','Агенттай шалгах']],school:[['Сургууль','600 м'],['Цэцэрлэг','450 м']],transport:[['Автобусны буудал','180 м'],['Гол зам','250 м']]};if(!items[tab])tab='convenience';modal(`<h2>Байршил ба ойр орчин</h2><p class="notice">Жишээ үзүүлэлтүүд. Бодит байгууламжийн байршил, зайг баталгаажуулаагүй.</p>${flowTabs(tabs,tab,'openNearbyFlow')}<div class="nearby-list">${items[tab].map(([name,distance],i)=>`<div><span class="nearby-symbol symbol-${tab}">${i+1}</span><b>${name}</b><span>${distance}</span></div>`).join('')}</div><button class="primary" onclick="openMapsMe()">Газрын зургийг MAPS.ME дээр нээх</button>`)}
function connectGlobalFlowEvents(){document.addEventListener('click',event=>{if(!event.target.closest('.search-container'))document.querySelectorAll('.search-suggestions').forEach(panel=>{panel.hidden=true;panel.previousElementSibling?.querySelector('input')?.setAttribute('aria-expanded','false')});if(!event.target.closest('#account-control')){const menu=document.querySelector('.account-dropdown');if(menu)menu.hidden=true}})}
function clearDemoData(){modal(`<h2>Демо мэдээлэл цэвэрлэх</h2><p>Энэ браузерт хадгалсан зар, хайлт, лавлагаа, нийтлэл, PRO ажлын бүртгэл болон ADMIN шийдвэр, мэдээ, түүхийг цэвэрлэнэ.</p><div class="flow-actions"><button onclick="closeOverlay()">Буцах</button><button class="primary" onclick="resetDemoStorage()">Цэвэрлэх</button></div>`)}
function resetDemoStorage(){for(const key of ['mn-saved','mn-recent','mn-flows'])localStorage.removeItem(key);saved=[];recent=[];for(const key of ['searches','bookmarks','complexSaved','complexRecent','requests','reports','posts','listings'])flowState[key]=[];flowState.profile={name:'Зочин',demo:false};flowState.draft={};flowState.pro={};flowState.admin={};flowState.neighborhood={};nhPlaceCache.clear();nhCancelPlaces();officeFilters={};officeReturnListing=null;listingPhotoDraft=[];editorReady=false;listingStep=0;for(let i=homes.length-1;i>=0;i--)if(homes[i].local)homes.splice(i,1);closeOverlay();render();toast('Демо мэдээлэл цэвэрлэгдлээ')}
